#include <iostream>
#include <vector>
#include <string>
#include <sstream>

using namespace std;

class AK375 {
public:
    string evaluate(int length, const string& inputStr) {
        string nestedSegments;
        string mainString;
        int maxSegmentLength = 0;
        int totalSegments = 0;

        for (int i = 0; i < length; i++) {
            char c = inputStr[i];
            if (c == '(') {
                nestedSegments += '_';
                int j = i + 1;
                while (j < length && inputStr[j] != ')') {
                    nestedSegments += inputStr[j];
                    j++;
                }
                i = j;
            } else if (c == ')') {
                mainString += '_';
            } else {
                mainString += c;
            }
        }

        // Split nestedSegments by '_'
        vector<string> nestedList;
        stringstream ssNested(nestedSegments);
        string part;
        while (getline(ssNested, part, '_')) {
            if (!part.empty()) {
                nestedList.push_back(part);
            }
        }
        totalSegments = nestedList.size();

        // Split mainString by '_'
        vector<string> mainParts;
        stringstream ssMain(mainString);
        while (getline(ssMain, part, '_')) {
            if (!part.empty()) {
                if ((int)part.length() > maxSegmentLength) {
                    maxSegmentLength = part.length();
                }
            }
        }

        return to_string(maxSegmentLength) + " " + to_string(totalSegments);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    AK375 solver;
    int n;
    while (cin >> n) {
        string s;
        cin >> s;
        string result = solver.evaluate(n, s);
        cout << result << "\n";
    }
    return 0;
}

